def binary_search(xs, target):
    """Binary search on a sorted list of distinct integers."""
    lo, hi = 0, len(xs) - 1          # start at 0 instead of 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        if xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
```

