def max_window_sum(xs, k):
    if k < 1 or k > len(xs):
        return None

    total = sum(xs[:k])
    best = total
    for i in range(k, len(xs)):
        total += xs[i] - xs[i - k]
        if total > best:
            best = total
    return best
```

